import math
import re
from fractions import Fraction

_NUM = r'\d+(?:\.\d+)?'

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_COMPONENT = re.compile(r'\s*(' + _NUM + r')\s*([A-Za-z]+)')
_ISO = re.compile(
    r'P(?:(' + _NUM + r')W)?(?:(' + _NUM + r')D)?'
    r'(T(?:(' + _NUM + r')H)?(?:(' + _NUM + r')M)?(?:(' + _NUM + r')S)?)?',
    re.IGNORECASE,
)
_CLOCK_FIELD = re.compile(r'\d+')
_CLOCK_LAST = re.compile(_NUM)


def _round_seconds(total: Fraction) -> int:
    return int(math.floor(total + Fraction(1, 2)))


def _parse_clock(s: str) -> Fraction:
    fields = s.split(':')
    if len(fields) not in (2, 3):
        raise ValueError(f"invalid clock duration: {s!r}")
    for f in fields[:-1]:
        if not _CLOCK_FIELD.fullmatch(f):
            raise ValueError(f"invalid clock duration: {s!r}")
    if not _CLOCK_LAST.fullmatch(fields[-1]):
        raise ValueError(f"invalid clock duration: {s!r}")
    nums = [Fraction(f) for f in fields]
    # Every field after the hours field must be below 60.
    for n in nums[1:]:
        if n >= 60:
            raise ValueError(f"invalid clock duration: {s!r}")
    total = Fraction(0)
    for n in nums:
        total = total * 60 + n
    return total


def _parse_iso(s: str) -> Fraction:
    m = _ISO.fullmatch(s)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")
    weeks, days, time_part, hours, minutes, seconds = m.group(1, 2, 3, 4, 5, 6)
    if weeks is None and days is None and time_part is None:
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")
    if time_part is not None and hours is None and minutes is None and seconds is None:
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")
    total = Fraction(0)
    if weeks is not None:
        total += Fraction(weeks) * 604800
    if days is not None:
        total += Fraction(days) * 86400
    if hours is not None:
        total += Fraction(hours) * 3600
    if minutes is not None:
        total += Fraction(minutes) * 60
    if seconds is not None:
        total += Fraction(seconds)
    return total


def _parse_components(s: str) -> Fraction:
    total = Fraction(0)
    pos = 0
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {s!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {s!r}")
        total += Fraction(m.group(1)) * _UNITS[unit]
        pos = m.end()
    return total


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    if re.fullmatch(r'\d+', s):
        return int(s)
    if s[0] in 'Pp':
        total = _parse_iso(s)
    elif ':' in s:
        total = _parse_clock(s)
    else:
        total = _parse_components(s)
    return _round_seconds(total)

